const mapPins={'Las Vegas, USA':[22,43],'Tokyo, Japan':[83,39],'Bangkok, Thailand':[76,53],'Kobe, Japan':[83,40],'Abu Dhabi, UAE':[63,46],'Ho Chi Minh City, Vietnam':[77,56],'Riyadh, Saudi Arabia':[61,45],'Doha, Qatar':[61,43],'Shanghai, China':[79,43],'Gliwice, Poland':[52,34]};
let events=[...fallbackEvents],active=events[0],filter='all',viewMonth=new Date(2026,10,1);
const days=document.querySelector('#days'),detail=document.querySelector('#detail'),monthTitle=document.querySelector('.panel-head h2');
const pad=n=>String(n).padStart(2,'0');
const kstMinutes=e=>{const t=(e.kst||'').match(/(\d{1,2}):(\d{2})/);return t?+t[1]*60 + +t[2]:1440};
const monthKey=()=>`${viewMonth.getFullYear()}-${pad(viewMonth.getMonth()+1)}`;
const dayKey=d=>`${monthKey()}-${pad(d)}`;
function renderDays(){
 monthTitle.textContent=`${viewMonth.getFullYear()}년 ${viewMonth.getMonth()+1}월`;
 const first=new Date(viewMonth.getFullYear(),viewMonth.getMonth(),1).getDay(),last=new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,0).getDate(),previous=new Date(viewMonth.getFullYear(),viewMonth.getMonth(),0).getDate(),cells=Math.ceil((first+last)/7)*7;
 days.innerHTML='';
 for(let i=0;i<cells;i++){const day=i-first+1,inMonth=day>0&&day<=last,shown=inMonth?day:(day<1?previous+day:new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,0).getDate()-(cells-i-1));const dayEvents=inMonth?events.filter(e=>e.date===dayKey(day)&&(filter==='all'||(e.categories||[e.cat]).includes(filter))).sort((a,b)=>kstMinutes(a)-kstMinutes(b)):[];const box=document.createElement('div');box.className='day'+(!inMonth?' muted':'')+(dayEvents.length?' has-events stack-'+dayEvents.length:'');box.innerHTML=`<span class="date">${shown}</span>${dayEvents.length>1?`<small class="event-count">${dayEvents.length} EVENTS</small>`:''}`;dayEvents.forEach(e=>{const b=document.createElement('button');b.className='event '+(((e.categories||[e.cat]).includes('major'))?'major':'');b.innerHTML=`${e.p}<span>${e.n}</span>`;b.onclick=()=>{active=e;renderDetail();document.querySelectorAll('.event').forEach(x=>x.classList.remove('focus'));b.classList.add('focus')};box.append(b)});days.append(box)}
}
function renderDetail(){const f=active.fights||[],p=mapPins[active.city]||[50,50],pairs=[];for(let i=0;i<f.length;i+=2)pairs.push([f[i],f[i+1]||['TBA','—']]);const links=[active.officialUrl&&`<a href="${active.officialUrl}" target="_blank" rel="noopener">공식 홈페이지</a>`,active.watchUrl&&`<a href="${active.watchUrl}" target="_blank" rel="noopener">티켓 / PPV</a>`].filter(Boolean).join('');detail.innerHTML=`<div class="detail-tag">${active.p} · ${active.cat==='major'?'MAJOR PROMOTION':'EVENT'}</div><h2>${active.n}</h2><div class="detail-date">${active.kst} · ${active.city}</div><div class="poster"><small>OFFICIAL POSTER AREA<br>API / CMS ASSET</small></div><div class="info"><div><b>현지 시작</b>${active.zone}</div><div><b>한국 시간</b>${active.kst}</div><div><b>개최 장소</b>${active.venue}</div><div><b>시청</b>${active.watch}</div></div><div class="map world-map"><div class="map-grid"></div><i class="pin" style="left:${p[0]}%;top:${p[1]}%"></i><span class="map-label">${active.city}</span></div><h3 class="card-heading">FIGHT ORDER <small>· 공식 카드 순서</small></h3>${pairs.length?pairs.map((pair,i)=>`<div class="fight"><i class="fighter-pic"></i><div>${pair[0][0]}<span>${pair[0][1]}</span></div><strong>${i===0?'MAIN':i+1}<br>VS</strong><div style="text-align:right">${pair[1][0]}<span>${pair[1][1]}</span></div></div>`).join(''):'<p class="fight-status">공식 대진 미발표</p>'}${links?`<div class="links">${links}</div>`:''}`}
document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelector('.filter.selected').classList.remove('selected');b.classList.add('selected');renderDays()});
document.querySelector('#prev').onclick=()=>{viewMonth.setMonth(viewMonth.getMonth()-1);renderDays()};document.querySelector('#next').onclick=()=>{viewMonth.setMonth(viewMonth.getMonth()+1);renderDays()};
function calendarUrl(){const d=active.date.replaceAll('-','');return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(active.p+' — '+active.n)}&dates=${d}T120000Z/${d}T160000Z&location=${encodeURIComponent(active.venue+', '+active.city)}&details=${encodeURIComponent('MMA CALENDAR 일정 · '+active.watch)}`}
document.querySelector('#googleCal').onclick=()=>window.open(calendarUrl(),'_blank','noopener');document.querySelector('#appleCal').onclick=()=>{window.location.href='calendar.ics'};
async function loadOfficialSchedule(){try{const response=await fetch('/api/events');if(!response.ok)return;const payload=await response.json();if(Array.isArray(payload.events)&&payload.events.length){events=payload.events.map(e=>({...e,date:e.date||e.start?.slice(0,10)}));active=events[0];renderDays();renderDetail()}}catch{ /* Static fallback remains usable while the scheduled importer is offline. */ }}
renderDays();renderDetail();loadOfficialSchedule();
